recipes.code:
{
  "inputs": [
    {
      "id": "klanex-api-key",
      "type": "promptString",
      "description": "klanex API key; klx_test_... keys route to the sandbox automatically",
      "password": true
    }
  ],
  "servers": {
    "klanex": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "klanex-mcp@0.1.0"
      ],
      "env": {
        "KLANEX_API_KEY": "${input:klanex-api-key}"
      }
    }
  }
}
